pub struct Matcher {
    pub pattern: String,
}

impl Matcher {
    pub fn find_in<'a>(&'a self, text: &str) -> Option<&'a str> {
        let i = text.find(&self.pattern)?;
        Some(&text[i..i + self.pattern.len()])
    }
}

